//! Consumes `fixtures/conformance_vectors.v1.json` — generated by
//! `tools/conformance-gen` from `cowprotocol/services`' own production
//! `model::order`/`model::signature` code, pinned to a specific services
//! commit (see the fixture's own `services_sha` field and
//! `tools/conformance-gen/README.md` for the regeneration procedure) —
//! and checks that this crate's `OrderData::{hash_struct,signing_hash,
//! recover_signer,uid}` independently reproduce every value for all 19
//! order vectors, under both signing schemes (38 checks total).
//!
//! This is the genuine services-execution oracle described in the CoW
//! DAO grant application (forum.cow.fi/t/3569): unlike the
//! `*_matches_ethers` tests in `src/order.rs`, nothing here is locked
//! against ethers.js. Every expected value in the fixture was computed by
//! calling `services`' own Rust code through its public API, not by
//! re-implementing its algorithm — including the EthSign digest, which
//! the generator obtains via `EcdsaSignature::recover(...).message`
//! rather than hand-rolling the EIP-191 wrapper.
//!
//! This is the Milestone 2 consumer test. The existing CI test job runs
//! `cargo test --workspace --all-targets`, so this test will execute on
//! every CI test run once it is committed.

use {
    alloy_primitives::{Address, B256, U256},
    cowprotocol_primitives::order_id::OrderUid,
    cowprotocol_signing::{
        domain::settlement_domain,
        order::{BuyTokenDestination, OrderData, OrderKind, SellTokenSource},
        signature::{Signature, ecdsa_from_components},
        signing_scheme::EcdsaSigningScheme,
    },
    serde::Deserialize,
    std::str::FromStr,
};

const EXPECTED_SCHEMA_VERSION: u32 = 1;
const EXPECTED_SERVICES_SHA: &str = "df6a14b12eab016f1ae939aa5b666658208b0bc0";
const EXPECTED_ORDER_VECTOR_COUNT: usize = 19;
const EXPECTED_SIGNING_SCHEME_CHECK_COUNT: usize = 38;

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    services_sha: String,
    chain_id: u64,
    settlement: String,
    order_vector_count: usize,
    signing_scheme_check_count: usize,
    vectors: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    id: String,
    sell_token: String,
    buy_token: String,
    receiver: Option<String>,
    sell_amount: String,
    buy_amount: String,
    valid_to: u32,
    app_data: String,
    fee_amount: String,
    kind: String,
    partially_fillable: bool,
    sell_token_balance: String,
    buy_token_balance: String,
    hash_struct: String,
    eip712_digest: String,
    ethsign_digest: String,
    eip712_signature: SigParts,
    eip712_recovered_owner: String,
    ethsign_signature: SigParts,
    ethsign_recovered_owner: String,
    uid: String,
}

#[derive(Deserialize)]
struct SigParts {
    r: String,
    s: String,
    v: u8,
}

fn addr(s: &str) -> Address {
    Address::from_str(s).unwrap()
}

fn b256(s: &str) -> B256 {
    B256::from_str(s).unwrap()
}

fn load_fixture() -> Fixture {
    let raw = include_str!("fixtures/conformance_vectors.v1.json");
    serde_json::from_str(raw).expect("fixture must parse")
}

#[test]
fn signed_order_conformance_corpus_v1() {
    let fixture = load_fixture();

    assert_eq!(
        fixture.schema_version, EXPECTED_SCHEMA_VERSION,
        "fixture schema_version must match what this consumer test was written against"
    );
    assert_eq!(
        fixture.services_sha, EXPECTED_SERVICES_SHA,
        "fixture must be pinned to the services commit this test expects"
    );
    assert_eq!(
        fixture.order_vector_count, EXPECTED_ORDER_VECTOR_COUNT,
        "coverage matrix must contain exactly the agreed 19 order vectors"
    );
    assert_eq!(
        fixture.signing_scheme_check_count, EXPECTED_SIGNING_SCHEME_CHECK_COUNT,
        "19 order vectors x 2 signing schemes must be exactly 38 checks"
    );
    assert_eq!(
        fixture.vectors.len(),
        fixture.order_vector_count,
        "vectors array length must match the declared order_vector_count"
    );

    let mut seen_ids = std::collections::HashSet::new();
    let mut signing_scheme_checks = 0usize;

    for v in &fixture.vectors {
        assert!(
            seen_ids.insert(v.id.clone()),
            "duplicate vector id: {}",
            v.id
        );

        let order = OrderData {
            sell_token: addr(&v.sell_token),
            buy_token: addr(&v.buy_token),
            receiver: v.receiver.as_deref().map(addr),
            sell_amount: U256::from_str(&v.sell_amount).unwrap(),
            buy_amount: U256::from_str(&v.buy_amount).unwrap(),
            valid_to: v.valid_to,
            app_data: b256(&v.app_data),
            fee_amount: U256::from_str(&v.fee_amount).unwrap(),
            kind: match v.kind.as_str() {
                "sell" => OrderKind::Sell,
                "buy" => OrderKind::Buy,
                other => panic!("{}: unknown kind {other}", v.id),
            },
            partially_fillable: v.partially_fillable,
            sell_token_balance: match v.sell_token_balance.as_str() {
                "erc20" => SellTokenSource::Erc20,
                "external" => SellTokenSource::External,
                "internal" => SellTokenSource::Internal,
                other => panic!("{}: unknown sell_token_balance {other}", v.id),
            },
            buy_token_balance: match v.buy_token_balance.as_str() {
                "erc20" => BuyTokenDestination::Erc20,
                "internal" => BuyTokenDestination::Internal,
                other => panic!("{}: unknown buy_token_balance {other}", v.id),
            },
        };

        let domain = settlement_domain(fixture.chain_id, addr(&fixture.settlement));

        // 1. OrderData struct hash.
        assert_eq!(
            order.hash_struct(),
            b256(&v.hash_struct),
            "{}: hash_struct diverges from services",
            v.id
        );

        // 2. EIP-712 signing digest.
        assert_eq!(
            order.signing_hash(EcdsaSigningScheme::Eip712, &domain),
            b256(&v.eip712_digest),
            "{}: EIP-712 digest diverges from services",
            v.id
        );
        signing_scheme_checks += 1;

        // 3. EthSign signing digest.
        assert_eq!(
            order.signing_hash(EcdsaSigningScheme::EthSign, &domain),
            b256(&v.ethsign_digest),
            "{}: EthSign digest diverges from services",
            v.id
        );
        signing_scheme_checks += 1;

        // 4. ECDSA recovered owner, both schemes.
        let eip712_sig = ecdsa_from_components(
            b256(&v.eip712_signature.r),
            b256(&v.eip712_signature.s),
            v.eip712_signature.v,
        )
        .unwrap();
        let eip712_recovered = order
            .recover_signer(&domain, &Signature::Eip712(eip712_sig))
            .unwrap()
            .expect("Eip712 recovers an owner");
        assert_eq!(
            eip712_recovered.signer,
            addr(&v.eip712_recovered_owner),
            "{}: EIP-712 recovered owner diverges from services",
            v.id
        );

        let ethsign_sig = ecdsa_from_components(
            b256(&v.ethsign_signature.r),
            b256(&v.ethsign_signature.s),
            v.ethsign_signature.v,
        )
        .unwrap();
        let ethsign_recovered = order
            .recover_signer(&domain, &Signature::EthSign(ethsign_sig))
            .unwrap()
            .expect("EthSign recovers an owner");
        assert_eq!(
            ethsign_recovered.signer,
            addr(&v.ethsign_recovered_owner),
            "{}: EthSign recovered owner diverges from services",
            v.id
        );

        // 5. Order UID packing.
        let uid = order.uid(&domain, eip712_recovered.signer);
        assert_eq!(
            uid.to_string(),
            v.uid,
            "{}: UID diverges from services",
            v.id
        );

        // UID split/rebuild is an identity, using cow-rs's own primitives.
        let parsed: OrderUid = v.uid.parse().unwrap();
        assert_eq!(parsed, uid, "{}: UID parse round-trip", v.id);
    }

    assert_eq!(
        signing_scheme_checks, EXPECTED_SIGNING_SCHEME_CHECK_COUNT,
        "must have performed exactly 38 signing-scheme digest checks (19 vectors x 2 schemes)"
    );
}
